test('createInvoice handles products with different VAT rates', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 1 },
      { sku: 'PRINT-A4', qty: 1 },
      { sku: 'WORKSHOP-DAY', qty: 1 },
    ],
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].vatRate, 21);
  assert.equal(result.value.lines[1].vatRate, 9);
  assert.equal(result.value.lines[2].vatRate, 0);
});

test('createInvoice does not mutate the input', () => {
  const input = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  };
  const originalLine = { ...input.lines[0] };
  createInvoice(input);
  assert.deepEqual(input.lines[0], originalLine);
});

test('lineTotal calculates qty × unitPrice', () => {
  const line = { qty: 10, unitPrice: 8500 };
  assert.equal(lineTotal(line), 85000);
});

test('lineTotal works with single quantity', () => {
  const line = { qty: 1, unitPrice: 1299 };
  assert.equal(lineTotal(line), 1299);
});

test('lineTotal works with large quantities', () => {
  const line = { qty: 1000, unitPrice: 50 };
  assert.equal(lineTotal(line), 50000);
});

test('invoiceTotals with a single line', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 8500 }],
  };
  const totals = invoiceTotals(invoice);
  assert.deepEqual(totals, { subtotal: 85000, total: 85000 });
});

test('invoiceTotals with multiple lines', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 8500 },
      { qty: 20, unitPrice: 9500 },
      { qty: 1, unitPrice: 120000 },
    ],
  };
  const totals = invoiceTotals(invoice);
  const expected = 5 * 8500 + 20 * 9500 + 1 * 120000;
  assert.equal(totals.subtotal, expected);
  assert.equal(totals.total, expected);
});

test('invoiceTotals returns new object', () => {
  const invoice = {
    lines: [{ qty: 1, unitPrice: 1000 }],
  };
  const totals1 = invoiceTotals(invoice);
  const totals2 = invoiceTotals(invoice);
  assert.notEqual(totals1, totals2);
  assert.deepEqual(totals1, totals2);
});

test('invoiceTotals works with an invoice from createInvoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 10 },
    ],
  });
  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  const expected = 5 * 8500 + 10 * 9500;
  assert.equal(totals.subtotal, expected);
  assert.equal(totals.total, expected);
});

